import clsx from "clsx";
import "./ToolIcon.scss";
import type { ToolButtonSize } from "./ToolButton";
const DEFAULT_SIZE: ToolButtonSize = "medium";
const GreenDotIcon = (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
    <circle cx="8" cy="8" r="6" fill="#22c55e" />
  </svg>
);
type CodeButtonProps = { isMobile?: boolean; };
export const CodeButton = (props: CodeButtonProps) => {
  return (
    <label className={clsx("ToolIcon ToolIcon__CodeButton", `ToolIcon_size_${DEFAULT_SIZE}`, { "is-mobile": props.isMobile })} title="Open Code Sandbox">
      <button className="ToolIcon_type_button" onClick={() => {
        const hash = window.location.hash;
        window.open(
          `/codecanvas/sandbox.html${hash}`,
          "code-sandbox",
          "width=960,height=700,resizable=yes,scrollbars=no"
        );
      }}
        aria-label="Open Code Sandbox"
        style={{ background: "none", border: "none", cursor: "pointer", width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center", color: "var(--icon-fill-color, #eee)" }}>
        {GreenDotIcon}
      </button>
    </label>
  );
};
