import { useEffect } from "react";
import { useAtomValue } from "jotai";
import { collabAPIAtom } from "../collab/Collab";

const POPUP_WINDOW_KEY = "__codeSandboxPopup";

const CodeSandboxBridge = () => {
  const collabAPI = useAtomValue(collabAPIAtom);

  useEffect(() => {
    // Store popup ref so it survives effect re-runs
    const handleReady = (event: MessageEvent) => {
      if (event.data?.type === "CODE_SANDBOX_READY") {
        (window as any)[POPUP_WINDOW_KEY] = event.source;
        // If collab is available now, wire up immediately
        if (collabAPI) {
          const popup = event.source as Window;
          collabAPI.setCodeUpdateCallback?.((code: string) => {
            if (popup && !popup.closed) {
              popup.postMessage({ type: "CODE_UPDATE", code }, "*");
            }
          });
        }
      }
    };

    // Forward code from popup to collab
    const handleCodeFromSandbox = (event: MessageEvent) => {
      if (event.data?.type === "CODE_FROM_SANDBOX" && collabAPI) {
        collabAPI.sendCode?.(event.data.code);
      }
    };

    window.addEventListener("message", handleReady);
    window.addEventListener("message", handleCodeFromSandbox);

    // On re-run: if collabAPI is now available and popup was already connected,
    // register the callback now
    if (collabAPI) {
      const popup = (window as any)[POPUP_WINDOW_KEY];
      if (popup && !popup.closed) {
        collabAPI.setCodeUpdateCallback?.((code: string) => {
          if (popup && !popup.closed) {
            popup.postMessage({ type: "CODE_UPDATE", code }, "*");
          }
        });
      }
    }

    return () => {
      window.removeEventListener("message", handleReady);
      window.removeEventListener("message", handleCodeFromSandbox);
    };
  }, [collabAPI]);

  return null;
};

export default CodeSandboxBridge;
